            ref = c.get('r')
            if not ref:
                continue
            ci, ri = col_to_idx(ref)
            t = c.get('t')
            val = None
            numeric = None

            inline = c.find(M + 'is')
            if inline is not None:
                val = ''.join(x.text or '' for x in inline.iter(M + 't'))

