            if v is not None and v.text is not None:
                raw = v.text
                if t == 's':
                    val = sst[int(raw)]
                elif t == 'b':
                    val = raw == '1'
                elif t == 'str':
                    val = raw
                elif t == 'e':
                    val = 'ERR:' + raw
                else:
                    try:
                        numeric = float(raw)
                        val = numeric
