                        val = raw

            f = c.find(M + 'f')
            if f is not None and val is None:
                val = '=' + (f.text or '')

            rows.setdefault(ri, {})[ci] = val
            if numeric is not None:
                sheet_total += numeric

        print(f"--- Sheet: {name} ---")
        for ri in sorted(rows):
            row = rows[ri]
            print(ri + 1, [row.get(ci) for ci in range(max(row) + 1)])
        print(f"Sheet numeric sum: {sheet_total}")
        grand_total += sheet_total

    print(f"\nGRAND TOTAL across all categories/sheets: {grand_total}")

